p: 2px;\n}\n\n/* ====== 大图预览 ====== */\n.preview-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 70;\n  background: rgba(0, 0, 0, 0.88);\n  backdrop-filter: blur(8px);\n  -webkit-backdrop-filter: blur(8px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 20px;\n}\n\n.preview-panel {\n  position: relative;\n  background: var(--vn-panel-bg);\n  border: 1px solid rgba(196, 162, 101, 0.3);\n  border-radius: 12px;\n  width: min(100%, 680px);\n  max-height: 90vh;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n  padding: 20px;\n  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.6);\n}\n\n.preview-full-img {\n  width: 100%;\n  max-height: 380px;\n  object-fit: contain;\n  border-radius: 8px;\n  background: rgba(0, 0, 0, 0.3);\n}\n\n.preview-info {\n  border-bottom: 1px solid rgba(196, 162, 101, 0.12);\n  padding-bottom: 12px;\n}\n\n.preview-title {\n  font-size: 1rem;\n  font-weight: 700;\n  color: var(--theme-text-main, var(--vn-fg));\n}\n\n.preview-meta {\n  font-size: 0.75rem;\n  color: var(--theme-text-muted, var(--vn-muted));\n  margin-top: 4px;\n}\n\n/* 操作栏 */\n.preview-actions {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.action-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.action-row.bottom {\n  justify-content: space-between;\n  padding-top: 8px;\n  border-top: 1px solid rgba(196, 162, 101, 0.1);\n}\n\n.action-label {\n  font-size: 0.78rem;\n  font-weight: 600;\n  color: var(--theme-text-muted, var(--vn-muted));\n  min-width: 36px;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n}\n\n.action-input {\n  flex: 1;\n  min-width: 120px;\n  padding: 6px 10px;\n  background: rgba(42, 36, 32, 0.5);\n  border: 1px solid rgba(196, 162, 101, 0.25);\n  border-radius: 6px;\n  color: var(--theme-text-main, var(--vn-fg));\n  font-size: 0.85rem;\n  outline: none;\n  transition: border-color 0.2s;\n}\n\n.action-input:focus { border-color: rgba(196, 162, 101, 0.55); }\n.action-input::placeholder { color: var(--theme-text-muted, var(--vn-muted)); }\n.action-input.url { min-width: 200px; }\n\n.action-btn {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 7px 14px;\n  background: rgba(42, 36, 32, 0.6);\n  border: 1px solid rgba(196, 162, 101, 0.3);\n  border-radius: 6px;\n  color: var(--theme-text-soft, var(--vn-muted));\n  font-size: 0.82rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.2s, border-color 0.2s, color 0.2s;\n  white-space: nowrap;\n}\n\n.action-btn:hover {\n  background: rgba(42, 36, 32, 0.9);\n  border-color: rgba(196, 162, 101, 0.5);\n  color: var(--theme-text-main, var(--vn-fg));\n}\n\n.action-btn.primary {\n  background: var(--theme-accent-soft, rgba(139, 69, 19, 0.7));\n  border-color: rgba(196, 162, 101, 0.4);\n  color: var(--paper-light);\n}\n\n.action-btn.primary:hover {\n  background: rgba(139, 69, 19, 0.95);\n  border-color: var(--theme-accent, var(--rust));\n}\n\n.action-btn.danger { color: rgba(220, 80, 80, 0.8); border-color: rgba(220, 80, 80, 0.3); }\n.action-btn.danger:hover { background: rgba(220, 80, 80, 0.15); border-color: rgba(220, 80, 80, 0.6); color: rgba(220, 80, 80, 1); }\n\n.hidden-input {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  opacity: 0;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n}\n\n.preview-close {\n  position: absolute;\n  top: 12px;\n  right: 12px;\n  width: 30px;\n  height: 30px;\n  border-radius: 50%;\n  background: rgba(0, 0, 0, 0.5);\n  border: 1px solid rgba(255, 255, 255, 0.2);\n  color: rgba(255, 255, 255, 0.8);\n  font-size: 14px;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: background 0.2s;\n}\n\n.preview-close:hover { background: rgba(139, 69, 19, 0.7); }\n\n/* ====== 动画 ====== */\n.panel-fade-enter-active, .panel-fade-leave-active { transition: opacity 0.2s; }\n.panel-fade-enter-from, .panel-fade-leave-to { opacity: 0; }\n\n.pre